import google.generativeai as genai

def image_summary(analysis_results, config=None):
    config = config or {}
    genai.configure(api_key=config['gemini_api_key'])
    model = genai.GenerativeModel('gemini-pro')

    prompt = """Summarize the following image analysis results:
Labels: {}
Description: {}
Detected Text: {}
Safety Scores (Adult: {}, Racy: {}, Gory: {}, Violence: {}):
""".format(
        ", ".join([label['name'] for label in analysis_results['labels']]),
        analysis_results['description'],
        analysis_results['text_content'],
        analysis_results['safety_scores']['adult']['is_adult_content'],
        analysis_results['safety_scores']['adult']['is_racy_content'],
        analysis_results['safety_scores']['adult']['is_gory_content'],
        analysis_results['safety_scores']['violence']['has_violence']
    )

    response = model.generate_content(prompt)
    return {'summary': response.text}

from google.cloud import translate_v2 as translate

def alt_text_translate(text, target_language, config=None):
    config = config or {}
    translate_client = translate.Client(credentials=config.get('google_credentials'))

    if isinstance(text, bytes):
        text = text.decode('utf-8')

    result = translate_client.translate(text, target_language=target_language)
    return {'translated_text': result['translatedText'], 'detected_source_language': result['detectedSourceLanguage']}

from google.cloud import storage

def image_asset_archive(image_bytes, file_name, bucket_name, config=None):
    config = config or {}
    storage_client = storage.Client(credentials=config.get('google_credentials'))
    bucket = storage_client.bucket(bucket_name)
    blob = bucket.blob(file_name)
    blob.upload_from_string(image_bytes, content_type='image/jpeg') # Assuming JPEG, adjust as needed
    return {'archive_url': blob.public_url}
